package com.slayerswaps;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class SlayerSwapsPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(SlayerSwapsPlugin.class);
		RuneLite.main(args);
	}
}

package com.slayerswaps;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import org.junit.Test;

public class SlayerDataTest
{
	private final SlayerData data = SlayerData.load(new Gson());

	@Test
	public void findsTasksByGameAndWikiNames()
	{
		assertEquals("Abyssal demons", data.findTask("Abyssal Demons").getName());
		assertEquals("Kurasks", data.findTask("Kurask").getName());
		assertEquals("Werewolves", data.findTask("Werewolf").getName());
		assertEquals("Jellies", data.findTask("Jelly").getName());
		assertNotNull(data.findTask("Thermonuclear smoke devil"));
		assertNull(data.findTask("Not a monster"));
	}

	@Test
	public void everyRouteTypeAndLocationIsKnown()
	{
		for (SlayerData.TaskData task : data.getTasks())
		{
			for (String location : task.getLocations())
			{
				assertNotNull(task.getName() + " -> " + location, data.location(location));
				for (SlayerData.Route route : data.routes(location))
				{
					assertNotNull(location + " " + route.getType(), route.routeType());
				}
			}
		}
		for (SlayerData.MasterData master : data.getMasters())
		{
			assertNotNull(master.getKey(), data.location(master.getLocation()));
		}
		for (SlayerMaster master : SlayerMaster.values())
		{
			assertTrue(master.name(), master == SlayerMaster.NONE || data.master(master.name()) != null);
		}
	}

	@Test
	public void defaultsUseTheBestTeleport()
	{
		assertEquals("Slayer Tower", data.findTask("Gargoyles").getLocations().get(0));
		assertEquals("Fremennik Slayer Dungeon", data.findTask("Kurask").getLocations().get(0));
		assertTrue(data.findTask("Abyssal demons").getLocations().contains("Abyssal Nexus"));
		assertTrue(data.location("Wilderness Slayer Cave").isWilderness());
		assertFalse(data.location("Slayer Tower").isWilderness());
	}
}

package com.slayerswaps;

import com.google.common.collect.ImmutableSet;
import com.google.gson.Gson;
import com.google.inject.Provides;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;
import java.util.Set;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.KeyCode;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.events.PostMenuSort;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Slayer Swaps",
	description = "Automatically swaps menu entries, and highlights teleport items and spells to quickly teleport to your slayer task. Supports choosing your preferred slayer master and preferred task location. To start right click your slayer helmet or check settings panel.",
	tags = {"slayer", "teleport", "menu", "swap", "ring", "fairy", "cape", "mortimer", "duradel", "highlight"}
)
public class SlayerSwapsPlugin extends Plugin
{
	// From [proc,helper_slayer_current_assignment], same as the core Slayer plugin
	private static final int BOSS_TASK_ID = 98;
	// SLAYER_MASTER varbit value for Krystilia, same as the core Slayer plugin
	private static final int KRYSTILIA = 7;

	private static final Set<MenuAction> OBJECT_MENU_TYPES = ImmutableSet.of(
		MenuAction.GAME_OBJECT_FIRST_OPTION, MenuAction.GAME_OBJECT_SECOND_OPTION, MenuAction.GAME_OBJECT_THIRD_OPTION,
		MenuAction.GAME_OBJECT_FOURTH_OPTION, MenuAction.GAME_OBJECT_FIFTH_OPTION);
	// Routes that are used by clicking an item (as opposed to a fairy ring, travel network or spellbook)
	private static final Set<RouteType> ITEM_ROUTES = ImmutableSet.of(RouteType.RING, RouteType.PORTAL,
		RouteType.MAXCAPE, RouteType.KARAMJA_GLOVES, RouteType.BURNING_AMULET, RouteType.RING_OF_DUELING,
		RouteType.AMULET_OF_GLORY, RouteType.BOAT, RouteType.ITEM, RouteType.SPELL);

	private static final String FAIRY_RING_CONFIGURE = "ring-configure";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	@Inject
	private SlayerSwapsConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private MenuHighlightOverlay menuHighlightOverlay;

	@Inject
	private TeleportItemOverlay teleportItemOverlay;

	@Inject
	private MenuHighlighter menuHighlighter;

	@Inject
	private TeleportItems teleportItems;

	@Inject
	private Gson gson;

	private SlayerData data;
	private SlayerSwapsPanel panel;
	private NavigationButton navButton;

	// Current task name as the game names it, or null when there is no task
	private String taskName;
	private boolean menusDirty;
	// The route whose item to outline: the first one in order that the player is carrying
	private SlayerData.Route carriedRoute;
	private boolean wearingSlayerHelmet;

	@Override
	protected void startUp()
	{
		data = SlayerData.load(gson);
		teleportItems.setData(data);
		menuHighlighter.setData(data);
		overlayManager.add(menuHighlightOverlay);
		overlayManager.add(teleportItemOverlay);

		panel = new SlayerSwapsPanel(data, new PanelChoices());
		navButton = NavigationButton.builder()
			.tooltip("Slayer Swaps")
			.icon(icon())
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		clientThread.invokeLater(this::updateTask);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(menuHighlightOverlay);
		overlayManager.remove(teleportItemOverlay);
		clientToolbar.removeNavigation(navButton);
		menuHighlighter.clear();
		taskName = null;
		carriedRoute = null;
		panel = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invokeLater(this::updateTask);
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		int varpId = event.getVarpId();
		if (varpId == VarPlayerID.SLAYER_COUNT
			|| varpId == VarPlayerID.SLAYER_TARGET
			|| event.getVarbitId() == VarbitID.SLAYER_TARGET_BOSSID
			|| event.getVarbitId() == VarbitID.SLAYER_MASTER)
		{
			clientThread.invokeLater(this::updateTask);
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (event.getGroup().equals(SlayerSwapsConfig.GROUP))
		{
			menusDirty = true;
			clientThread.invokeLater(this::updateCarriedRoute);
			String key = event.getKey();
			if (key.equals("slayerMaster"))
			{
				// Choosing a master in settings counts as the first-time choice, so the helmet stops asking
				configManager.setConfiguration(SlayerSwapsConfig.GROUP, SlayerSwapsConfig.MASTER_CHOSEN_KEY, true);
			}
			SlayerSwapsPanel p = panel;
			if (p != null && !key.startsWith(SlayerSwapsConfig.LOCATION_KEY_PREFIX)
				&& !key.startsWith(SlayerSwapsConfig.ROUTE_KEY_PREFIX)
				&& !key.startsWith(SlayerSwapsConfig.DISABLED_KEY_PREFIX))
			{
				// Teleport and Wilderness settings change which locations and teleports the panel offers
				SwingUtilities.invokeLater(p::refresh);
			}
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.WORN)
		{
			updateSlayerHelmet();
		}
		if (event.getContainerId() == InventoryID.INV || event.getContainerId() == InventoryID.WORN)
		{
			updateCarriedRoute();
		}
	}

	private void updateSlayerHelmet()
	{
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		Item head = worn == null ? null : worn.getItem(EquipmentInventorySlot.HEAD.getSlotIdx());
		boolean wearing = head != null && head.getId() > 0
			&& client.getItemDefinition(head.getId()).getName().toLowerCase().contains("slayer helmet");
		if (wearing != wearingSlayerHelmet)
		{
			wearingSlayerHelmet = wearing;
			menusDirty = true;
		}
	}

	private void updateTask()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		updateSlayerHelmet();

		int remaining = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
		String name = remaining > 0 ? lookupTaskName(client.getVarpValue(VarPlayerID.SLAYER_TARGET)) : null;
		SlayerData.TaskData task = data.findTask(name);

		if (!Objects.equals(name, taskName))
		{
			taskName = name;
			menusDirty = true;
			updateCarriedRoute();
			if (name != null && task == null)
			{
				log.debug("Task {} isn't in the location data", name);
			}
			log.debug("Task is now {} ({} left), master {}, location {}, routes {}",
				taskName, remaining, client.getVarbitValue(VarbitID.SLAYER_MASTER), currentLocation(), currentRoutes());
			if (task != null)
			{
				askForLocation(task);
			}
		}

		SlayerSwapsPanel p = panel;
		if (p != null)
		{
			SwingUtilities.invokeLater(() -> p.setCurrentTask(task, remaining));
		}
	}

	/**
	 * The first time a task with more than one location comes up, say how to choose one.
	 */
	private void askForLocation(SlayerData.TaskData task)
	{
		if (!config.askOnNewTask() || isDisabled(task) || taskLocations(task, true).size() < 2
			|| configManager.getConfiguration(SlayerSwapsConfig.GROUP, locationKey(task.getName())) != null)
		{
			return;
		}

		String message = new ChatMessageBuilder()
			.append("Slayer Swaps: right-click your slayer helmet to choose where to do " + task.getName()
				+ ". Using " + currentLocation() + " until you do.")
			.build();
		chatMessageManager.queue(QueuedMessage.builder().type(ChatMessageType.GAMEMESSAGE).runeLiteFormattedMessage(message).build());
	}

	/**
	 * Adds a client-side "Slayer Swaps" option to the slayer helmet's right-click menu while there's a first-time
	 * choice to make: the current task's location, or the slayer master when there's no task. After that the
	 * choice is changed in the panel. Nothing is sent to the server; choosing just stores the choice in config.
	 */
	private void addHelmetChooser(MenuEntry[] entries)
	{
		int helmetIdx = -1;
		for (int i = 0; i < entries.length; i++)
		{
			int itemId = itemIdOf(entries[i]);
			if (itemId > 0 && client.getItemDefinition(itemId).getName().toLowerCase().contains("slayer helmet"))
			{
				helmetIdx = i;
				break;
			}
		}
		if (helmetIdx == -1)
		{
			return;
		}

		SlayerData.TaskData task = data.findTask(taskName);
		if (task != null)
		{
			List<String> locations = taskLocations(task, true);
			if (isDisabled(task) || locations.size() < 2
				|| configManager.getConfiguration(SlayerSwapsConfig.GROUP, locationKey(task.getName())) != null)
			{
				return;
			}

			Menu sub = chooserEntry(helmetIdx, "Choose location", task.getName()).createSubMenu();
			String current = currentLocation();
			for (int i = locations.size() - 1; i >= 0; i--)
			{
				String location = locations.get(i);
				sub.createMenuEntry(0)
					.setOption(location.equals(current) ? ColorUtil.wrapWithColorTag(location, Color.GREEN) : location)
					.setType(MenuAction.RUNELITE)
					.onClick(e ->
					{
						configManager.setConfiguration(SlayerSwapsConfig.GROUP, locationKey(task.getName()), location);
						chat("Slayer Swaps: " + task.getName() + " set to " + location + ". Change it any time in the Slayer Swaps panel.");
					});
			}
		}
		else if (configManager.getConfiguration(SlayerSwapsConfig.GROUP, SlayerSwapsConfig.MASTER_CHOSEN_KEY) == null)
		{
			Menu sub = chooserEntry(helmetIdx, "Choose slayer master", "").createSubMenu();
			SlayerMaster[] masters = SlayerMaster.values();
			for (int i = masters.length - 1; i >= 0; i--)
			{
				SlayerMaster master = masters[i];
				sub.createMenuEntry(0)
					.setOption(master == config.slayerMaster() ? ColorUtil.wrapWithColorTag(master.toString(), Color.GREEN) : master.toString())
					.setType(MenuAction.RUNELITE)
					.onClick(e ->
					{
						configManager.setConfiguration(SlayerSwapsConfig.GROUP, "slayerMaster", master);
						configManager.setConfiguration(SlayerSwapsConfig.GROUP, SlayerSwapsConfig.MASTER_CHOSEN_KEY, true);
						chat("Slayer Swaps: slayer master set to " + master + ". Change it any time in the plugin settings.");
					});
			}
		}
	}

	private MenuEntry chooserEntry(int index, String option, String target)
	{
		return client.getMenu().createMenuEntry(index)
			.setOption(ColorUtil.wrapWithColorTag("Slayer Swaps: ", Color.ORANGE) + option)
			.setTarget(target)
			.setType(MenuAction.RUNELITE);
	}

	private void chat(String text)
	{
		String message = new ChatMessageBuilder().append(text).build();
		chatMessageManager.queue(QueuedMessage.builder().type(ChatMessageType.GAMEMESSAGE).runeLiteFormattedMessage(message).build());
	}

	private String lookupTaskName(int taskId)
	{
		int taskRow;
		if (taskId == BOSS_TASK_ID)
		{
			List<Integer> bossRows = client.getDBRowsByValue(
				DBTableID.SlayerTaskSublist.ID,
				DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID,
				0,
				client.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID));
			if (bossRows.isEmpty())
			{
				return null;
			}
			taskRow = (Integer) client.getDBTableField(bossRows.get(0), DBTableID.SlayerTaskSublist.COL_TASK, 0)[0];
		}
		else
		{
			List<Integer> taskRows = client.getDBRowsByValue(DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0, taskId);
			if (taskRows.isEmpty())
			{
				return null;
			}
			taskRow = taskRows.get(0);
		}

		return (String) client.getDBTableField(taskRow, DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0)[0];
	}

	/**
	 * @param current true for the player's current task, where Krystilia's tasks are limited to the Wilderness
	 * @return the locations a task can be done at with at least one enabled teleport, best first
	 */
	private List<String> taskLocations(SlayerData.TaskData task, boolean current)
	{
		boolean krystilia = current && client.getVarbitValue(VarbitID.SLAYER_MASTER) == KRYSTILIA;
		List<String> locations = new ArrayList<>();
		for (String location : task.getLocations())
		{
			SlayerData.LocationData info = data.location(location);
			if (info == null || enabledRoutes(location).isEmpty())
			{
				continue;
			}
			// Krystilia's tasks only count in the Wilderness
			if (krystilia ? !info.isWilderness() : info.isWilderness() && !config.wilderness())
			{
				continue;
			}
			locations.add(location);
		}
		return locations;
	}

	private String chosenLocation(SlayerData.TaskData task, List<String> locations)
	{
		if (locations.isEmpty())
		{
			return null;
		}
		String chosen = configManager.getConfiguration(SlayerSwapsConfig.GROUP, locationKey(task.getName()));
		return locations.contains(chosen) ? chosen : locations.get(0);
	}

	/**
	 * @return where teleports should take the player right now, or null to leave menus alone
	 */
	String currentLocation()
	{
		if (taskName == null)
		{
			SlayerData.MasterData master = data.master(config.slayerMaster().name());
			return master != null ? master.getLocation() : null;
		}

		SlayerData.TaskData task = data.findTask(taskName);
		return task == null || isDisabled(task) ? null : chosenLocation(task, taskLocations(task, true));
	}

	/**
	 * @return the enabled teleports to the current location, with the player's chosen teleport first
	 */
	List<SlayerData.Route> currentRoutes()
	{
		if (config.onlyWithSlayerHelmet() && !wearingSlayerHelmet)
		{
			return Collections.emptyList();
		}
		if (taskName == null)
		{
			SlayerData.MasterData master = data.master(config.slayerMaster().name());
			return master != null ? filterEnabled(master.getRoutes()) : Collections.emptyList();
		}

		String location = currentLocation();
		if (location == null)
		{
			return Collections.emptyList();
		}

		List<SlayerData.Route> routes = new ArrayList<>(enabledRoutes(location));
		String chosen = configManager.getConfiguration(SlayerSwapsConfig.GROUP, routeKey(taskName));
		for (int i = 0; i < routes.size(); i++)
		{
			if (Routes.key(routes.get(i)).equals(chosen))
			{
				routes.add(0, routes.remove(i));
				break;
			}
		}
		return routes;
	}

	private List<SlayerData.Route> enabledRoutes(String location)
	{
		return filterEnabled(data.routes(location));
	}

	private List<SlayerData.Route> filterEnabled(List<SlayerData.Route> routes)
	{
		List<SlayerData.Route> enabled = new ArrayList<>();
		for (SlayerData.Route route : routes)
		{
			RouteType type = route.routeType();
			if (type != null && config.isEnabled(type))
			{
				enabled.add(route);
			}
		}
		return enabled;
	}

	/**
	 * Finds the first item-based route to the current location that the player is carrying.
	 */
	private void updateCarriedRoute()
	{
		carriedRoute = null;
		List<Integer> carried = carriedItemIds();
		for (SlayerData.Route route : currentRoutes())
		{
			if (!ITEM_ROUTES.contains(route.routeType()))
			{
				continue;
			}
			for (int itemId : carried)
			{
				if (teleportItems.matches(itemId, route))
				{
					carriedRoute = route;
					return;
				}
			}
		}
	}

	private List<Integer> carriedItemIds()
	{
		List<Integer> ids = new ArrayList<>();
		for (int containerId : new int[]{InventoryID.INV, InventoryID.WORN})
		{
			ItemContainer container = client.getItemContainer(containerId);
			if (container != null)
			{
				for (Item item : container.getItems())
				{
					if (item.getId() > 0)
					{
						ids.add(item.getId());
					}
				}
			}
		}
		return ids;
	}

	/**
	 * @return true if this item should be outlined: it's the teleport to use for the current location
	 */
	boolean shouldHighlight(int itemId)
	{
		SlayerData.Route route = carriedRoute;
		return route != null && teleportItems.matches(itemId, route);
	}

	private boolean isDisabled(SlayerData.TaskData task)
	{
		return Boolean.parseBoolean(configManager.getConfiguration(SlayerSwapsConfig.GROUP,
			SlayerSwapsConfig.DISABLED_KEY_PREFIX + SlayerData.normalize(task.getName())));
	}

	private static String locationKey(String task)
	{
		return SlayerSwapsConfig.LOCATION_KEY_PREFIX + SlayerData.normalize(task);
	}

	private static String routeKey(String task)
	{
		return SlayerSwapsConfig.ROUTE_KEY_PREFIX + SlayerData.normalize(task);
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		menusDirty = true;
		if (log.isDebugEnabled())
		{
			int group = event.getGroupId();
			clientThread.invokeLater(() -> logInterface(group));
		}
		clientThread.invokeLater(this::updateMenuHighlights);
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		menusDirty = true;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		// Teleport dialogs are often built by scripts after the interface loads, so rescan each tick
		menusDirty = true;
		updateMenuHighlights();
	}

	private void updateMenuHighlights()
	{
		if (!menusDirty)
		{
			return;
		}
		menusDirty = false;
		menuHighlighter.update(config.highlightMenus() ? currentRoutes() : Collections.emptyList());
	}

	// Runs after the Menu Entry Swapper (priority 0), so our swap wins over a custom swap there
	@Subscribe(priority = -1)
	public void onPostMenuSort(PostMenuSort event)
	{
		// The menu isn't rebuilt while it's open, so swapping now would swap repeatedly
		if (client.isMenuOpen() || client.isKeyPressed(KeyCode.KC_SHIFT))
		{
			return;
		}

		List<SlayerData.Route> routes = currentRoutes();
		if (routes.isEmpty())
		{
			return;
		}

		if (swapItem(routes))
		{
			return;
		}
		for (SlayerData.Route route : routes)
		{
			if (route.routeType() == RouteType.FAIRY && swapFairyRing(route.getValue()))
			{
				return;
			}
		}
	}

	/**
	 * Puts a teleport item's option for the current location on left-click.
	 */
	private boolean swapItem(List<SlayerData.Route> routes)
	{
		Menu menu = client.getMenu();
		MenuEntry[] entries = menu.getMenuEntries();
		for (int i = entries.length - 1; i >= 0; i--)
		{
			MenuEntry entry = entries[i];
			int itemId = itemIdOf(entry);
			if (itemId <= 0)
			{
				continue;
			}

			for (SlayerData.Route route : routes)
			{
				if (route.getValue() == null || !teleportItems.matches(itemId, route))
				{
					continue;
				}

				if (optionMatches(entry.getOption(), route.getValue()))
				{
					moveToTop(menu, entries, i);
					return true;
				}

				Menu sub = entry.getSubMenu();
				if (sub != null)
				{
					for (MenuEntry subEntry : sub.getMenuEntries())
					{
						if (optionMatches(subEntry.getOption(), route.getValue()))
						{
							clone(subEntry);
							return true;
						}
					}
				}
			}
		}
		return false;
	}

	private static boolean optionMatches(String option, String value)
	{
		return Text.removeTags(option).trim().equalsIgnoreCase(value);
	}

	/**
	 * Puts the fairy ring option for a code on left-click: a favourite or last-destination option naming
	 * the code if there is one, otherwise Configure so the code can be picked from the fairy ring log.
	 */
	private boolean swapFairyRing(String code)
	{
		Pattern codePattern = Pattern.compile("\\b" + code + "\\b");
		Menu menu = client.getMenu();
		MenuEntry[] entries = menu.getMenuEntries();
		int configureIdx = -1;

		for (int i = entries.length - 1; i >= 0; i--)
		{
			MenuEntry entry = entries[i];
			if (!isFairyRing(entry))
			{
				continue;
			}

			String option = Text.removeTags(entry.getOption());
			if (codePattern.matcher(option).find())
			{
				moveToTop(menu, entries, i);
				return true;
			}

			Menu sub = entry.getSubMenu();
			if (sub != null)
			{
				for (MenuEntry subEntry : sub.getMenuEntries())
				{
					if (codePattern.matcher(Text.removeTags(subEntry.getOption())).find())
					{
						clone(subEntry);
						return true;
					}
				}
			}

			if (configureIdx == -1 && option.equalsIgnoreCase(FAIRY_RING_CONFIGURE))
			{
				configureIdx = i;
			}
		}

		if (configureIdx != -1)
		{
			moveToTop(menu, entries, configureIdx);
			return true;
		}
		return false;
	}

	private static boolean isFairyRing(MenuEntry entry)
	{
		return OBJECT_MENU_TYPES.contains(entry.getType())
			&& Text.removeTags(entry.getTarget()).toLowerCase().contains("fairy");
	}

	private static void moveToTop(Menu menu, MenuEntry[] entries, int index)
	{
		int top = entries.length - 1;
		if (index == top)
		{
			return;
		}

		MenuEntry entry = entries[index];
		// Item op4 and op5 are low priority, which makes them right-click only
		if (entry.getType() == MenuAction.CC_OP_LOW_PRIORITY)
		{
			entry.setType(MenuAction.CC_OP);
		}
		entries[index] = entries[top];
		entries[top] = entry;
		menu.setMenuEntries(entries);
	}

	/**
	 * @return the item id an inventory or worn item menu entry is for, or -1
	 */
	private static int itemIdOf(MenuEntry entry)
	{
		Widget w = entry.getWidget();
		if (w == null)
		{
			return -1;
		}

		int interfaceId = WidgetUtil.componentToInterface(w.getId());
		if (interfaceId == InterfaceID.INVENTORY)
		{
			return w.getItemId();
		}
		if (interfaceId == InterfaceID.WORNITEMS)
		{
			Widget child = w.getChild(1);
			return child != null ? child.getItemId() : -1;
		}
		return -1;
	}

	private void clone(MenuEntry menuEntry)
	{
		// A submenu entry can't be moved to the top level, so copy it there; same as the Menu Entry Swapper
		client.getMenu().createMenuEntry(-1)
			.setOption(menuEntry.getOption())
			.setTarget(menuEntry.getTarget())
			.setIdentifier(menuEntry.getIdentifier())
			.setType(menuEntry.getType() == MenuAction.CC_OP_LOW_PRIORITY ? MenuAction.CC_OP : menuEntry.getType())
			.setItemId(menuEntry.getItemId())
			.setParam0(menuEntry.getParam0())
			.setParam1(menuEntry.getParam1())
			.onClick(menuEntry.onClick());
	}

	// Development aid: logs every right-click menu so option names can be read from the log
	// instead of guessed. Debug level, so it's silent in normal clients.
	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		addHelmetChooser(event.getMenuEntries());
		if (!log.isDebugEnabled())
		{
			return;
		}

		log.debug("Menu opened (task {}, location {}):", taskName, currentLocation());
		for (MenuEntry entry : event.getMenuEntries())
		{
			logEntry("  ", entry);
			Menu sub = entry.getSubMenu();
			if (sub != null)
			{
				for (MenuEntry subEntry : sub.getMenuEntries())
				{
					logEntry("    > ", subEntry);
				}
			}
		}
	}

	private static void logEntry(String prefix, MenuEntry e)
	{
		log.debug("{}option='{}' target='{}' type={} id={} itemId={} widgetItemId={} p0={} p1={}",
			prefix, Text.removeTags(e.getOption()), Text.removeTags(e.getTarget()), e.getType(),
			e.getIdentifier(), e.getItemId(), itemIdOf(e), e.getParam0(), e.getParam1());
	}

	// Development aid: logs the text of newly opened interfaces, to find how teleport menus label destinations
	private void logInterface(int group)
	{
		List<String> texts = new ArrayList<>();
		Widget[] roots = client.getWidgetRoots();
		if (roots != null)
		{
			for (Widget root : roots)
			{
				collectTexts(root, group, texts);
			}
		}
		if (!texts.isEmpty())
		{
			log.debug("Interface {} opened: {}", group, texts.size() > 60 ? texts.subList(0, 60) : texts);
		}
	}

	private static void collectTexts(Widget w, int group, List<String> out)
	{
		if (w == null || w.isHidden())
		{
			return;
		}
		if (WidgetUtil.componentToInterface(w.getId()) == group)
		{
			if (w.getText() != null && !w.getText().isEmpty())
			{
				out.add(Text.removeTags(w.getText()));
			}
			else if (w.getName() != null && !w.getName().isEmpty())
			{
				out.add("[" + Text.removeTags(w.getName()) + "]");
			}
		}
		for (Widget[] children : new Widget[][]{w.getStaticChildren(), w.getDynamicChildren(), w.getNestedChildren()})
		{
			if (children != null)
			{
				for (Widget child : children)
				{
					collectTexts(child, group, out);
				}
			}
		}
	}

	private static BufferedImage icon()
	{
		// A simple map pin, so no image file is needed
		BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(0xC0392B));
		g.fillOval(3, 1, 10, 10);
		g.fillPolygon(new int[]{4, 12, 8}, new int[]{8, 8, 15}, 3);
		g.setColor(Color.WHITE);
		g.setStroke(new BasicStroke(1.5f));
		g.drawOval(6, 4, 4, 4);
		g.dispose();
		return image;
	}

	/**
	 * Lets the side panel read and change per-task choices. Panel calls come from the Swing thread.
	 */
	private class PanelChoices implements SlayerSwapsPanel.Choices
	{
		@Override
		public String location(SlayerData.TaskData task)
		{
			return chosenLocation(task, locations(task));
		}

		@Override
		public String routeKey(SlayerData.TaskData task)
		{
			return configManager.getConfiguration(SlayerSwapsConfig.GROUP, SlayerSwapsPlugin.routeKey(task.getName()));
		}

		@Override
		public List<String> locations(SlayerData.TaskData task)
		{
			List<String> locations = new ArrayList<>();
			for (String location : task.getLocations())
			{
				SlayerData.LocationData info = data.location(location);
				if (info != null && !enabledRoutes(location).isEmpty() && (!info.isWilderness() || config.wilderness()))
				{
					locations.add(location);
				}
			}
			return locations;
		}

		@Override
		public List<SlayerData.Route> routes(String location)
		{
			return enabledRoutes(location);
		}

		@Override
		public void choose(SlayerData.TaskData task, String location, String routeKey)
		{
			configManager.setConfiguration(SlayerSwapsConfig.GROUP, locationKey(task.getName()), location);
			if (routeKey == null)
			{
				configManager.unsetConfiguration(SlayerSwapsConfig.GROUP, SlayerSwapsPlugin.routeKey(task.getName()));
			}
			else
			{
				configManager.setConfiguration(SlayerSwapsConfig.GROUP, SlayerSwapsPlugin.routeKey(task.getName()), routeKey);
			}
			log.debug("{}: location {}, teleport {}", task.getName(), location, routeKey == null ? "best carried" : routeKey);
		}

		@Override
		public boolean isEnabled(SlayerData.TaskData task)
		{
			return !isDisabled(task);
		}

		@Override
		public void setEnabled(SlayerData.TaskData task, boolean enabled)
		{
			String key = SlayerSwapsConfig.DISABLED_KEY_PREFIX + SlayerData.normalize(task.getName());
			if (enabled)
			{
				configManager.unsetConfiguration(SlayerSwapsConfig.GROUP, key);
			}
			else
			{
				configManager.setConfiguration(SlayerSwapsConfig.GROUP, key, true);
			}
		}
	}

	@Provides
	SlayerSwapsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SlayerSwapsConfig.class);
	}
}

package com.slayerswaps;

import com.google.common.collect.ImmutableSet;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.ItemID;

/**
 * Decides which teleport items serve which routes. Most items are matched by name, so every charge count and
 * variant (eternal glory, trimmed capes, ornament kits) counts as the same item.
 */
@Singleton
class TeleportItems
{
	private static final Set<Integer> SLAYER_RINGS = ImmutableSet.of(
		ItemID.SLAYER_RING_1, ItemID.SLAYER_RING_2, ItemID.SLAYER_RING_3, ItemID.SLAYER_RING_4,
		ItemID.SLAYER_RING_5, ItemID.SLAYER_RING_6, ItemID.SLAYER_RING_7, ItemID.SLAYER_RING_8,
		ItemID.SLAYER_RING_ETERNAL);
	private static final Set<Integer> BURNING_AMULETS = ImmutableSet.of(
		ItemID.BURNING_AMULET_1, ItemID.BURNING_AMULET_2, ItemID.BURNING_AMULET_3, ItemID.BURNING_AMULET_4,
		ItemID.BURNING_AMULET_5);
	private static final Set<Integer> RINGS_OF_DUELING = ImmutableSet.of(
		ItemID.RING_OF_DUELING_1, ItemID.RING_OF_DUELING_2, ItemID.RING_OF_DUELING_3, ItemID.RING_OF_DUELING_4,
		ItemID.RING_OF_DUELING_5, ItemID.RING_OF_DUELING_6, ItemID.RING_OF_DUELING_7, ItemID.RING_OF_DUELING_8);

	private final Client client;
	private final Map<Integer, String> names = new HashMap<>();
	private SlayerData data;

	@Inject
	TeleportItems(Client client)
	{
		this.client = client;
	}

	void setData(SlayerData data)
	{
		this.data = data;
	}

	private String name(int itemId)
	{
		return names.computeIfAbsent(itemId, id -> client.getItemDefinition(id).getName().toLowerCase());
	}

	/**
	 * @return true if this item can be used for the route. Call on the client thread.
	 */
	boolean matches(int itemId, SlayerData.Route route)
	{
		RouteType type = route.routeType();
		if (itemId <= 0 || type == null)
		{
			return false;
		}

		String name = name(itemId);
		String value = route.getValue() == null ? "" : route.getValue().toLowerCase();
		switch (type)
		{
			case RING:
				return SLAYER_RINGS.contains(itemId);
			case KARAMJA_GLOVES:
				return itemId == ItemID.ATJUN_GLOVES_ELITE;
			case BURNING_AMULET:
				return BURNING_AMULETS.contains(itemId);
			case RING_OF_DUELING:
				return RINGS_OF_DUELING.contains(itemId);
			case AMULET_OF_GLORY:
				// "Amulet of glory(1-6)", "Amulet of glory(t1-t6)" and "Amulet of eternal glory"
				return name.startsWith("amulet of") && name.contains("glory");
			case PORTAL:
				// Construction cape, max cape, or a redirected house tablet like "Rimmington teleport"
				return isMaxCape(name) || name.startsWith("construct. cape") || name.equals(value + " teleport");
			case MAXCAPE:
				return isMaxCape(name);
			case BOAT:
				return isMaxCape(name) || name.startsWith("sailing cape") || name.equals("teleport to boat");
			case SPELL:
				// The spell's tablet has the same name
				return name.equals(value);
			case ITEM:
				SlayerData.ItemData item = data == null ? null : data.getItems().get(route.getItem());
				if (item != null)
				{
					for (String prefix : item.getNames())
					{
						if (name.startsWith(prefix))
						{
							return true;
						}
					}
				}
				return false;
			default:
				return false;
		}
	}

	/**
	 * @return true if the item is any teleport item the plugin knows, for placing the location picker
	 */
	boolean isTeleportItem(int itemId)
	{
		if (itemId <= 0)
		{
			return false;
		}
		if (SLAYER_RINGS.contains(itemId) || BURNING_AMULETS.contains(itemId) || RINGS_OF_DUELING.contains(itemId)
			|| itemId == ItemID.ATJUN_GLOVES_ELITE)
		{
			return true;
		}
		String name = name(itemId);
		if (isMaxCape(name) || name.startsWith("construct. cape") || name.contains("teleport")
			|| (name.startsWith("amulet of") && name.contains("glory")))
		{
			return true;
		}
		if (data != null)
		{
			for (SlayerData.ItemData item : data.getItems().values())
			{
				for (String prefix : item.getNames())
				{
					if (name.startsWith(prefix))
					{
						return true;
					}
				}
			}
		}
		return false;
	}

	private static boolean isMaxCape(String name)
	{
		return name.contains("max cape");
	}
}

package com.slayerswaps;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * Kinds of teleport a location can be reached by. The type names match the "type" field in slayer_locations.json.
 */
@Getter
@RequiredArgsConstructor
public enum RouteType
{
	RING("ring", "Slayer ring"),
	FAIRY("fairy", "Fairy ring"),
	PORTAL("portal", "House portal (construction / max cape)"),
	MAXCAPE("maxcape", "Max cape"),
	KARAMJA_GLOVES("karamja_gloves", "Karamja gloves 4"),
	BURNING_AMULET("burning_amulet", "Burning amulet"),
	RING_OF_DUELING("ring_of_dueling", "Ring of dueling"),
	AMULET_OF_GLORY("amulet_of_glory", "Amulet of glory"),
	BOAT("boat", "Teleport to Boat"),
	ITEM("item", "Teleport item"),
	SPELL("spell", "Spell or tablet"),
	NETWORK("network", "Travel network");

	private final String key;
	private final String displayName;

	static RouteType forKey(String key)
	{
		for (RouteType type : values())
		{
			if (type.key.equals(key))
			{
				return type;
			}
		}
		return null;
	}
}

package com.slayerswaps;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.IconTextField;

/**
 * Side panel for choosing, per task, which location to go to and which teleport to use.
 * Swing code; runs on the event dispatch thread.
 */
class SlayerSwapsPanel extends PluginPanel
{
	static final String AUTO = "Best teleport I'm carrying";

	interface Choices
	{
		String location(SlayerData.TaskData task);

		String routeKey(SlayerData.TaskData task);

		List<String> locations(SlayerData.TaskData task);

		List<SlayerData.Route> routes(String location);

		void choose(SlayerData.TaskData task, String location, String routeKey);

		boolean isEnabled(SlayerData.TaskData task);

		void setEnabled(SlayerData.TaskData task, boolean enabled);
	}

	private final SlayerData data;
	private final Choices choices;
	private final JLabel current = new JLabel();
	private final JPanel currentRow = new JPanel(new BorderLayout());
	private final JPanel list = new JPanel();
	private final List<TaskRow> rows = new ArrayList<>();

	SlayerSwapsPanel(SlayerData data, Choices choices)
	{
		this.data = data;
		this.choices = choices;
		setLayout(new BorderLayout(0, 8));

		JPanel top = new JPanel();
		top.setLayout(new BoxLayout(top, BoxLayout.Y_AXIS));
		JLabel title = new JLabel("Slayer Swaps");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		top.add(title);
		top.add(Box.createVerticalStrut(6));
		current.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		top.add(current);
		top.add(Box.createVerticalStrut(4));
		top.add(currentRow);
		top.add(Box.createVerticalStrut(8));

		IconTextField search = new IconTextField();
		search.setIcon(IconTextField.Icon.SEARCH);
		search.setPreferredSize(new Dimension(PANEL_WIDTH - 20, 30));
		search.getDocument().addDocumentListener(new DocumentListener()
		{
			public void insertUpdate(DocumentEvent e)
			{
				filter(search.getText());
			}

			public void removeUpdate(DocumentEvent e)
			{
				filter(search.getText());
			}

			public void changedUpdate(DocumentEvent e)
			{
				filter(search.getText());
			}
		});
		top.add(search);
		add(top, BorderLayout.NORTH);

		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		List<SlayerData.TaskData> tasks = new ArrayList<>(data.getTasks());
		tasks.sort(Comparator.comparing(t -> t.getName().toLowerCase()));
		for (SlayerData.TaskData task : tasks)
		{
			if (choices.locations(task).isEmpty())
			{
				continue;
			}
			TaskRow row = new TaskRow(task);
			rows.add(row);
			list.add(row);
		}
		add(list, BorderLayout.CENTER);
		setCurrentTask(null, 0);
	}

	void setCurrentTask(SlayerData.TaskData task, int remaining)
	{
		currentRow.removeAll();
		if (task == null)
		{
			current.setText("No slayer task");
		}
		else
		{
			current.setText("Current task: " + task.getName() + " (" + remaining + " left)");
			currentRow.add(new TaskRow(task), BorderLayout.CENTER);
		}
		currentRow.revalidate();
		currentRow.repaint();
	}

	void refresh()
	{
		for (TaskRow row : rows)
		{
			row.load();
		}
	}

	private void filter(String text)
	{
		String q = text.trim().toLowerCase();
		for (TaskRow row : rows)
		{
			row.setVisible(q.isEmpty() || row.task.getName().toLowerCase().contains(q)
				|| row.task.getLocations().stream().anyMatch(l -> l.toLowerCase().contains(q)));
		}
		list.revalidate();
	}

	private class TaskRow extends JPanel
	{
		private final SlayerData.TaskData task;
		private final JComboBox<String> location = new JComboBox<>();
		private final JComboBox<RouteItem> route = new JComboBox<>();
		private final JCheckBox enabled;
		private boolean loading;

		TaskRow(SlayerData.TaskData task)
		{
			this.task = task;
			this.enabled = new JCheckBox(task.getName());
			enabled.setForeground(Color.WHITE);
			setLayout(new GridLayout(3, 1, 0, 2));
			setBorder(BorderFactory.createEmptyBorder(4, 0, 6, 0));
			enabled.setToolTipText("Untick to never swap or highlight teleports for this task");
			add(enabled);
			add(location);
			add(route);
			enabled.addActionListener(e ->
			{
				if (!loading)
				{
					choices.setEnabled(task, enabled.isSelected());
					updateEnabled();
				}
			});
			location.addActionListener(e ->
			{
				if (!loading)
				{
					fillRoutes(null);
					save();
				}
			});
			route.addActionListener(e ->
			{
				if (!loading)
				{
					save();
				}
			});
			load();
		}

		void load()
		{
			loading = true;
			location.removeAllItems();
			for (String l : choices.locations(task))
			{
				location.addItem(l);
			}
			location.setSelectedItem(choices.location(task));
			fillRoutes(choices.routeKey(task));
			enabled.setSelected(choices.isEnabled(task));
			updateEnabled();
			loading = false;
		}

		private void updateEnabled()
		{
			location.setEnabled(enabled.isSelected());
			route.setEnabled(enabled.isSelected());
		}

		private void fillRoutes(String selectedKey)
		{
			boolean wasLoading = loading;
			loading = true;
			route.removeAllItems();
			route.addItem(new RouteItem(null, AUTO));
			String loc = (String) location.getSelectedItem();
			if (loc != null)
			{
				for (SlayerData.Route r : choices.routes(loc))
				{
					RouteItem item = new RouteItem(Routes.key(r), Routes.describe(data, r));
					route.addItem(item);
					if (item.key.equals(selectedKey))
					{
						route.setSelectedItem(item);
					}
				}
			}
			loading = wasLoading;
		}

		private void save()
		{
			RouteItem r = (RouteItem) route.getSelectedItem();
			choices.choose(task, (String) location.getSelectedItem(), r == null ? null : r.key);
		}
	}

	private static class RouteItem
	{
		private final String key;
		private final String text;

		RouteItem(String key, String text)
		{
			this.key = key;
			this.text = text;
		}

		@Override
		public String toString()
		{
			return text;
		}
	}
}

package com.slayerswaps;

/**
 * Human-readable descriptions of routes, for the side panel and chat messages.
 */
final class Routes
{
	private Routes()
	{
	}

	static String describe(SlayerData data, SlayerData.Route route)
	{
		RouteType type = route.routeType();
		String value = route.getValue();
		if (type == null)
		{
			return route.getType() + ": " + value;
		}
		switch (type)
		{
			case FAIRY:
				return "Fairy ring " + value;
			case SPELL:
				return value + " (spell/tablet)";
			case ITEM:
				SlayerData.ItemData item = data.getItems().get(route.getItem());
				String label = item != null ? item.getLabel() : route.getItem();
				return value == null ? label : label + ": " + value;
			case NETWORK:
				SlayerData.NetworkData network = data.getNetworks().get(route.getItem());
				return (network != null ? network.getLabel() : route.getItem()) + ": " + value;
			case PORTAL:
				return "House portal: " + value;
			case BOAT:
				return "Boat moored at " + value;
			default:
				return type.getDisplayName() + ": " + value;
		}
	}

	/**
	 * Stable key for remembering a chosen route in config.
	 */
	static String key(SlayerData.Route route)
	{
		return route.getType() + "|" + (route.getItem() == null ? "" : route.getItem()) + "|"
			+ (route.getValue() == null ? "" : route.getValue());
	}
}

package com.slayerswaps;

import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Outlines the destination to pick in open teleport menus.
 */
class MenuHighlightOverlay extends Overlay
{
	private final MenuHighlighter highlighter;
	private final SlayerSwapsConfig config;

	@Inject
	MenuHighlightOverlay(MenuHighlighter highlighter, SlayerSwapsConfig config)
	{
		this.highlighter = highlighter;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.highlightMenus())
		{
			return null;
		}

		graphics.setColor(config.highlightColor());
		graphics.setStroke(new BasicStroke(2));
		for (Widget w : highlighter.getHighlighted())
		{
			if (!w.isHidden())
			{
				Rectangle bounds = w.getBounds();
				graphics.drawRect(bounds.x - 1, bounds.y - 1, bounds.width + 2, bounds.height + 2);
			}
		}
		return null;
	}
}

package com.slayerswaps;

import com.google.common.collect.ImmutableMap;
import com.google.common.collect.ImmutableSet;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.util.Text;

/**
 * Finds the option for the current destination in open teleport menus (max cape, construction cape, fairy ring
 * log, item dialogs, travel networks, boat teleport) and teleport spells in the spellbook. An interface only counts
 * as a menu for a route if it shows several of that route's known destinations, so a destination name appearing
 * elsewhere isn't highlighted.
 */
@Singleton
class MenuHighlighter
{
	private static final Pattern KEY_PREFIX = Pattern.compile("^[0-9a-z]\\s*[.:)]\\s+");
	private static final Pattern FAIRY_CODE = Pattern.compile("^[a-d][i-l][p-s]$");

	private static final Set<String> PORTALS = ImmutableSet.of("home", "rimmington", "taverley", "pollnivneach",
		"hosidius", "aldarin", "rellekka", "brimhaven", "yanille", "prifddinas");
	private static final Set<String> MAXCAPE = ImmutableSet.<String>builder().addAll(PORTALS)
		.add("warrior's guild", "fishing guild", "crafting guild", "farming guild", "otto's grotto",
			"feldip hunter area", "wilderness hunter area", "hunter guild", "the pandemonium", "boat", "last boat")
		.build();
	private static final Map<RouteType, Set<String>> FAMILIES = ImmutableMap.<RouteType, Set<String>>builder()
		.put(RouteType.PORTAL, PORTALS)
		.put(RouteType.MAXCAPE, MAXCAPE)
		.put(RouteType.BURNING_AMULET, ImmutableSet.of("chaos temple", "bandit camp", "lava maze"))
		.put(RouteType.RING_OF_DUELING, ImmutableSet.of("emir's arena", "castle wars", "ferox enclave", "fortis colosseum"))
		.put(RouteType.KARAMJA_GLOVES, ImmutableSet.of("gem mine", "slayer master"))
		.put(RouteType.AMULET_OF_GLORY, ImmutableSet.of("edgeville", "karamja", "draynor village", "al kharid"))
		.build();

	private final Client client;

	private SlayerData data;
	private List<Widget> highlighted = Collections.emptyList();

	@Inject
	MenuHighlighter(Client client)
	{
		this.client = client;
	}

	void setData(SlayerData data)
	{
		this.data = data;
	}

	List<Widget> getHighlighted()
	{
		return highlighted;
	}

	void clear()
	{
		highlighted = Collections.emptyList();
	}

	/**
	 * Rescans open interfaces for the given routes' options. Call on the client thread.
	 */
	void update(Collection<SlayerData.Route> routes)
	{
		if (routes.isEmpty())
		{
			clear();
			return;
		}

		// Labelled widgets of every open interface, grouped by interface
		Map<Integer, List<Widget>> byGroup = new HashMap<>();
		Widget[] roots = client.getWidgetRoots();
		if (roots != null)
		{
			for (Widget root : roots)
			{
				collect(root, byGroup);
			}
		}

		List<Widget> found = new ArrayList<>();
		for (List<Widget> widgets : byGroup.values())
		{
			for (SlayerData.Route route : routes)
			{
				RouteType type = route.routeType();
				if (type == null || route.getValue() == null || !isMenuFor(type, route, widgets))
				{
					continue;
				}
				for (Widget w : widgets)
				{
					if (matches(type, route.getValue(), w))
					{
						found.add(w);
					}
				}
			}
		}
		highlighted = found;
	}

	private static void collect(Widget w, Map<Integer, List<Widget>> byGroup)
	{
		if (w == null || w.isHidden())
		{
			return;
		}

		if (!isEmpty(w.getText()) || !isEmpty(w.getName()))
		{
			byGroup.computeIfAbsent(WidgetUtil.componentToInterface(w.getId()), k -> new ArrayList<>()).add(w);
		}

		collectAll(w.getStaticChildren(), byGroup);
		collectAll(w.getDynamicChildren(), byGroup);
		collectAll(w.getNestedChildren(), byGroup);
	}

	private static void collectAll(Widget[] children, Map<Integer, List<Widget>> byGroup)
	{
		if (children != null)
		{
			for (Widget child : children)
			{
				collect(child, byGroup);
			}
		}
	}

	private boolean isMenuFor(RouteType type, SlayerData.Route route, List<Widget> widgets)
	{
		switch (type)
		{
			case FAIRY:
				return widgets.stream().filter(w -> FAIRY_CODE.matcher(label(w).replace(" ", "")).matches()).count() >= 2;
			case BOAT:
				return widgets.stream().anyMatch(w -> label(w).contains("boat"));
			case SPELL:
				// The spellbook: several widgets named after teleport spells
				return widgets.stream().filter(w -> name(w).endsWith(" teleport")).count() >= 3;
			case NETWORK:
				SlayerData.NetworkData network = data == null ? null : data.getNetworks().get(route.getItem());
				return network != null && countKnown(widgets, lower(network.getDestinations())) >= 2;
			case ITEM:
				SlayerData.ItemData item = data == null ? null : data.getItems().get(route.getItem());
				return item != null && countKnown(widgets, lower(item.getOptions())) >= 2;
			default:
				Set<String> family = FAMILIES.get(type);
				return family != null && countKnown(widgets, family) >= 2;
		}
	}

	private static long countKnown(List<Widget> widgets, Set<String> known)
	{
		return widgets.stream().map(MenuHighlighter::label).filter(known::contains).distinct().count();
	}

	private static Set<String> lower(List<String> values)
	{
		Set<String> out = new HashSet<>();
		for (String v : values)
		{
			out.add(v.toLowerCase());
		}
		return out;
	}

	private static boolean matches(RouteType type, String value, Widget w)
	{
		String target = value.toLowerCase();
		switch (type)
		{
			case FAIRY:
				return label(w).replace(" ", "").equals(target);
			case BOAT:
				return label(w).contains(target);
			case SPELL:
				return name(w).equals(target);
			default:
				return label(w).equals(target);
		}
	}

	/**
	 * Text of a widget, lower-cased with tags and any hotkey prefix like "1. " or "B: " removed.
	 */
	static String label(Widget w)
	{
		if (isEmpty(w.getText()))
		{
			return "";
		}
		String text = Text.removeTags(w.getText()).trim().toLowerCase();
		return KEY_PREFIX.matcher(text).replaceFirst("");
	}

	private static String name(Widget w)
	{
		return isEmpty(w.getName()) ? "" : Text.removeTags(w.getName()).trim().toLowerCase();
	}

	private static boolean isEmpty(String s)
	{
		return s == null || s.isEmpty();
	}
}

